            console.log("Vulnerability not Exist: Drawn card differs from prediction");
        }

        vm.stopPrank();
        // Final test assertion remains for correctness check
        assertEq(lastCard, expectedCard, "Weak PRNG: Drawn card did not match prediction");
    }
}
